<header class="admin-header"><div><span class="eyebrow">Moderation</span><h1>Civic issues</h1></div></header><section class="admin-panel table-wrap"><table><thead><tr><th>Issue</th><th>Citizen</th><th>Moderation</th><th>Progress</th><th>Update</th></tr></thead><tbody><?php foreach($issues as $i):?><tr><td><strong><?=e($i['title'])?></strong><small><?=e($i['category'].' · '.$i['locality'])?></small></td><td><?=e($i['full_name'])?></td><td colspan="3"><form class="row-form" method="post" action="<?=url('admin/issues/'.$i['id'])?>"><?=csrf_field()?><?=method_field('PUT')?><select name="moderation_status"><?php foreach(['pending','approved','rejected','hidden'] as $s):?><option<?=selected($i['moderation_status'],$s)?>><?=e($s)?></option><?php endforeach;?></select><select name="progress_status"><?php foreach(['reported','under_review','action_initiated','escalated','resolved','closed'] as $s):?><option<?=selected($i['progress_status'],$s)?>><?=e($s)?></option><?php endforeach;?></select><input name="public_update" placeholder="Public update"><input name="internal_notes" placeholder="Internal note"><label><input type="checkbox" name="is_featured" <?=$i['is_featured']?'checked':''?>> Featured</label><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></section>
